class MovesState(rx.State):
    """Sort / filter / tab state of the r1 widget, shared by every AI-first page."""

    query: str = ""
    sort_col: int = -1
    sort_desc: bool = False
    widths: list[int] = [width for _, width in COLUMNS]
    tab: str = "table"

    @rx.var
    def rows(self) -> list[list[str]]:
        needle = self.query.strip().lower()
        rows = [r for r in ROWS if needle in " ".join(r).lower()] if needle else list(ROWS)
        if self.sort_col >= 0:
            rows.sort(key=lambda r: _sort_key(r[self.sort_col]), reverse=self.sort_desc)
        return rows

    @rx.var
    def row_count(self) -> int:
        return len(self.rows)

    @rx.var
    def columns(self) -> list[dict[str, Any]]:
        arrow = " ▼" if self.sort_desc else " ▲"
        return [
            {"title": name + (arrow if i == self.sort_col else ""), "id": name, "type": "str", "width": self.widths[i]}
            for i, (name, _) in enumerate(COLUMNS)
        ]

    @rx.event
    def set_query(self, value: str):
        self.query = value

    @rx.event
    def set_tab(self, tab: str):
        self.tab = tab

    @rx.event
    def header_clicked(self, pos: tuple[int, int]):
        # Glide sends the bare column index here, despite the (col, row) tuple in Reflex's event spec.
        col = pos if isinstance(pos, int) else pos[0]
        if col != self.sort_col:
            self.sort_col, self.sort_desc = col, False
        elif not self.sort_desc:
            self.sort_desc = True
        else:
            self.sort_col, self.sort_desc = -1, False

    @rx.event
    def column_resized(self, column: dict[str, Any], width: int):
        names = [name for name, _ in COLUMNS]
        if column.get("id") in names:
            self.widths[names.index(column["id"])] = int(width)


def handle(name: str) -> rx.Component:
    """A named result both the agent and Python can refer to."""
    return rx.el.span(name, class_name="handle mono")


def grid(height: str = "300px") -> rx.Component:
    return rx.el.div(
        rx.data_editor(
            columns=MovesState.columns,
            data=MovesState.rows,
            rows=MovesState.row_count,
            theme=GRID_THEME,
            row_markers="number",
            row_height=28,
            header_height=32,
            smooth_scroll_x=True,
            smooth_scroll_y=True,
            column_select="none",
            on_header_clicked=MovesState.header_clicked,
            on_column_resize=MovesState.column_resized,
            height=height,
        ),
        style={"height": height},
    )


def chart(height: int = 300, width: int | str = "100%") -> rx.Component:
    return rx.recharts.bar_chart(
        rx.recharts.cartesian_grid(stroke=BG3, horizontal=False),
        rx.recharts.bar(data_key="advantage", fill=RED, radius=[0, 3, 3, 0], is_animation_active=False),
        rx.recharts.x_axis(type_="number", domain=[-30, 0], stroke=GREY1),
        rx.recharts.y_axis(data_key="move", type_="category", width=150, stroke=GREY1),
        rx.recharts.graphing_tooltip(
            cursor={"fill": BG1},
            content_style={"background": BG_DIM, "border": f"1px solid {BG4}", "borderRadius": "6px"},
            item_style={"color": FG},
        ),
        data=CHART_DATA,
        layout="vertical",
        width=width,
        height=height,
    )


def _tab(name: str, label: str) -> rx.Component:
    return rx.el.button(
        label,
        on_click=MovesState.set_tab(name),
        class_name=rx.cond(MovesState.tab == name, "viewer-tab is-active", "viewer-tab"),
    )


def r1_widget(height: int = 300, actions: bool = True) -> rx.Component:
    """The tool output as an interactive widget: sortable grid, chart tab, filter, follow-up actions."""
    return rx.el.div(
        rx.el.div(
            handle("r1"),
            rx.el.span(f"framedata · {R1_SHAPE}", class_name="dim"),
            rx.el.span(class_name="spacer"),
            rx.el.input(placeholder="Filter rows…", on_change=MovesState.set_query, class_name="viewer-filter"),
            rx.el.div(_tab("table", "Table"), _tab("chart", "Chart"), class_name="viewer-tabs"),
            class_name="viewer-bar sans",
        ),
        rx.cond(
            MovesState.tab == "table",
            grid(f"{height}px"),
            rx.el.div(chart(height - 16), class_name="widget-chart", style={"height": f"{height}px"}),
        ),
        rx.el.div(
            rx.el.button(rx.el.span(ICON_PY, class_name="mono"), " Use in Python", class_name="act"),
            rx.el.button(rx.el.span(ICON_AI, class_name="mono"), " Ask about this", class_name="act"),
            rx.el.button("Pin", class_name="act"),
            rx.el.span(class_name="spacer"),
            rx.el.span("click a header to sort", class_name="dim"),
            class_name="widget-actions sans",
        )
        if actions
        else rx.fragment(),
        class_name="widget",
    )


def tool_step(name: str, args: str, result: rx.Component | str) -> rx.Component:
    """One agent tool call, collapsed to a single line."""
    return rx.el.div(
        rx.el.span("▸", class_name="dim"),
        rx.el.span(name, class_name="tool-name"),
        rx.el.span(f"({args})", class_name="tool-args"),
        rx.el.span("→", class_name="dim"),
        result if isinstance(result, rx.Component) else rx.el.span(result, class_name="dim"),
        class_name="tool-step mono",
    )


def tool_steps() -> rx.Component:
    return rx.el.div(
        tool_step("find_character", '"little mac"', "little_mac"),
        tool_step("query_smashdb", "\"SELECT move, startup, … WHERE char_id = 'little_mac'\"", handle("r1")),
        class_name="tool-steps",
    )


def safe_table(limit: int | None = None) -> rx.Component:
    rows = SAFE_ROWS if limit is None else SAFE_ROWS[:limit]
    return rx.el.table(
        rx.el.thead(
            rx.el.tr(rx.el.th("move"), rx.el.th("startup", class_name="num"), rx.el.th("advantage", class_name="num"))
        ),
        rx.el.tbody(
            *[
                rx.el.tr(rx.el.td(r[0]), rx.el.td(r[1], class_name="num"), rx.el.td(r[2], class_name="num"))
                for r in rows
            ]
        ),
        class_name="df mono",
    )


def py_code(start: int | None = None) -> rx.Component:
    return code_block(PY_LINES, start=start)


def composer(placeholder: str, context: list[str], active: str = "ai") -> rx.Component:
    """Bottom input shared by the AI-first looks: mode pills, context handles, prompt."""
    modes = [("ai", ICON_AI, "Ask"), ("python", ICON_PY, "Python"), ("smash", ICON_DB, "SQL")]
    return rx.el.div(
        rx.el.div(
            *[
                rx.el.span(
                    rx.el.span(icon, class_name="mono"),
                    f" {label}",
                    class_name=f"pill m-{mode}" + (" is-active" if mode == active else ""),
                )
                for mode, icon, label in modes
            ],
            rx.el.span(class_name="spacer"),
            *[handle(name) for name in context],
            class_name="composer-top sans",
        ),
        rx.el.div(
            rx.el.span(placeholder, class_name="dim"),
            rx.el.span(" ", class_name="cursor"),
            class_name="composer-input mono",
        ),
        class_name="composer",
    )
